-- HB3 (fatia 11) · Cronograma da obra: quadro "Mão de obra e clima por semana" (histograma de horas apontadas + dias de
-- chuva e parados do diário/RDO) e "?" do quadro e dos 4 indicadores (RD-95). Aditiva (só texto de ajuda).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, 'Cronograma da obra', v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/projetos/obras/[id]/cronograma', 'hub_construcao', 'publicado'
FROM (VALUES
 ('projetos.cronograma.histograma', 'Mão de obra e clima por semana', 'Nada a preencher: as barras somam as horas apontadas na obra (OS de obra ou tela de horas) e o clima vem do diário (RDO) de cada dia.', 'Mostra, semana a semana, quanta gente trabalhou na obra e quantos dias a chuva atrapalhou. Compare com o cronograma: semana com poucas horas ou muitos dias parados explica atraso e ajuda a pedir prorrogação de prazo com prova.', 'Semana de 12/10: 96 h (equipe média 2,4 pessoas), 2 dias de chuva, 1 dia parado.', 'Não apontar as horas no dia: a barra fica baixa e parece que a equipe não trabalhou.', 40),
 ('projetos.cronograma.ind_horas', 'Horas apontadas', 'Nada a preencher: soma de todas as horas apontadas nesta obra.', 'É o esforço de mão de obra já gasto na obra. Junto do avanço físico, mostra se a produtividade está dentro do previsto.', '312 h apontadas com 45% de avanço.', 'Apontar horas de outra obra nesta: o total sobe sem a obra andar.', 41),
 ('projetos.cronograma.ind_pico', 'Pico semanal', 'Nada a preencher: a semana com mais horas apontadas.', 'Mostra o maior efetivo que a obra já teve numa semana. Ajuda a planejar alojamento, EPI e transporte da equipe.', 'Pico de 120 h: três pessoas a semana inteira.', 'Ler o pico como média: a maior parte das semanas costuma ter menos gente.', 42),
 ('projetos.cronograma.ind_chuva', 'Dias de chuva', 'Nada a preencher: conta os dias em que o diário (RDO) marcou chuva ou chuva forte.', 'Prova os dias de chuva da obra. Mostra "—" quando a obra ainda não tem diário.', '4 dias de chuva em outubro.', 'Registrar o clima da previsão do tempo, não o que aconteceu no canteiro.', 43),
 ('projetos.cronograma.ind_parados', 'Dias parados', 'Nada a preencher: conta os dias em que o diário (RDO) marcou que não deu para trabalhar.', 'São os dias perdidos da obra (chuva, falta de material, liberação do cliente). Base para justificar atraso e pedir aditivo de prazo.', '2 dias parados por chuva forte.', 'Marcar "deu para trabalhar" num dia em que a equipe ficou parada: o atraso perde a justificativa.', 44)
) AS v(chave, rotulo, o_que, para_que, exemplo, erro, ordem)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
